        },
        {
            chapter = "Anthion and the Dead Man's Plea",
            follows = false,
            summaryAlliance = "Deliana in Ironforge wants Mux's new Ghost Revealer put to work. Take it to the gates of Stratholme, switch it on, and see whether the ghost of Anthion Harmon has anything to say.",
            summaryHorde = "Mokvar in Orgrimmar wants Mux's new Ghost Revealer put to work. Take it to the gates of Stratholme, switch it on, and see whether the ghost of Anthion Harmon has anything to say.",
            recap = "The Ghost Revealer, it turns out, works. I switched it on at the gates of Stratholme, and there stood Anthion Harmon, dead and waiting, with a plea. Baron Rivendare had Ysida Harmon somewhere inside, and time was short.\n\nSo we ran Stratholme. Not walked. Ran, through the whole rotten city to the Baron himself, and we got there in time. Ysida gave me a locket to carry out, so Anthion would know it was true.\n\nThe dead don't stay sentimental for long when there's work left. Next thing I knew, Anthion had me fetching iron, leather and cloth for a banner, and the unfinished banner was going to an old friend of his in Dire Maul. These jobs never get shorter.",
            quests = {
                { id = 8929, name = "In Search of Anthion", npc = "Deliana", faction = "Alliance" },
                { id = 8930, name = "In Search of Anthion", npc = "Mokvar", faction = "Horde" },
                { id = 8945, name = "Dead Man's Plea", npc = "Anthion Harmon" },
                { id = 8946, name = "Proof of Life", npc = "Ysida Harmon" },
                { id = 8947, name = "Anthion's Strange Request", npc = "Anthion Harmon" },
                { id = 8948, name = "Anthion's Old Friend", npc = "Anthion Harmon" },
            },
        },
        {
            chapter = "Falrin's Vendetta",
            summary = "Anthion's unfinished banner is in the hands of Falrin Treeshaper, in the Athenaeum at Dire Maul. Before anything else, Falrin has a vendetta against the ogres to settle, and it runs to twenty-five warbeads.",
            recap = "Anthion's old friend was Falrin Treeshaper, in the library at Dire Maul. Falrin looked at the unfinished banner and agreed to help, right after a small matter of ogres. Falrin has a vendetta. I never got the whole story. I got a number, twenty-five, and that's how many warbeads I took off ogres before Falrin was satisfied.\n\nAn enchantment and some more shopping later, I was holding the Banner of Provocation, which is exactly what it sounds like. Plant it in the right place and somebody comes looking for a fight.\n\nFalrin even had the place picked out: the Ring of Law, in Blackrock Depths. Some people send flowers.",
            quests = {
                { id = 8949, name = "Falrin's Vendetta", npc = "Falrin Treeshaper" },
                { id = 8950, name = "The Instigator's Enchantment", npc = "Falrin Treeshaper" },
                { id = 7494, name = "Feathermoon Stronghold", npc = "Crier Goodman", faction = "Alliance", optional = true, breadcrumbFor = 7488 },
                { id = 7488, name = "Lethtendris's Web", npc = "Latronicus Moonspear", faction = "Alliance", optional = true, recap = "Lethtendris had built a web in Dire Maul to soak up the magic leaking out of the place, and fancied herself its master. Latronicus Moonspear at Feathermoon thought otherwise and wanted the web, to let the magic out over the wilds and then smash the thing. I settled the argument for them." },
                { id = 7492, name = "Camp Mojache", npc = "Warcaller Gorlach", faction = "Horde", optional = true, breadcrumbFor = 7489 },
                { id = 7489, name = "Lethtendris's Web", npc = "Talo Thornhoof", faction = "Horde", optional = true, recap = "Lethtendris had built a web in Dire Maul to soak up the magic leaking out of the place, and meant to aim it at her enemies. Talo Thornhoof at Camp Mojache reckoned she'd never hand it over alive, and Talo was right. The web went off to someone more responsible, which by then was nearly anybody." },
                { id = 7482, name = "Elven Legends", npc = "Scholar Runethorn", faction = "Alliance", optional = true, recap = "Scholar Runethorn at Feathermoon was after an old elven master whose trail ran from Quel'Thalas all the way to Dire Maul, along with a cartload of lost artifacts. I found where the trail ended. Runethorn took the news hard, and the lack of artifacts harder." },
                { id = 7481, name = "Elven Legends", npc = "Sage Korolusk", faction = "Horde", optional = true, recap = "Sage Korolusk at Camp Mojache was after an old elven master whose trail ran from Quel'Thalas all the way to Dire Maul, along with a cartload of lost artifacts. I found where the trail ended. Korolusk took the news hard, and the lack of artifacts harder." },
                { id = 7441, name = "Pusillin and the Elder Azj'Tordin", npc = "Azj'Tordin", optional = true, recap = "Azj'Tordin, an old Shen'dralar lying low at the Lariss Pavilion, had been robbed by an imp called Pusillin: one Book of Incantations, with the key to Dire Maul thrown in. Getting the book back meant chasing Pusillin all over the Warpwood Quarter. Azj'Tordin regretted nothing, and I only regretted the running." },
                { id = 7461, name = "The Madness Within", npc = "Shen'dralar Ancient", optional = true },
                { id = 7877, altIds = { 7462 }, name = "The Treasure of the Shen'dralar", npc = "Shen'dralar Ancient", optional = true, recap = "The Shen'dralar Ancient in the courtyard wanted the madness in Dire Maul ended, which meant five pylons, one caged demon, and finally Prince Tortheldrin. I'd been warned the Prince was persuasive, and he wasn't persuasive enough. The reward was a chest tucked under the library stairs, which is exactly where I'd hide treasure too." },
                { id = 98830, name = "The Broken Glaive", npc = "Tortheldrin's Broken Glaive", optional = true, gameVersions = { forever = true }, recap = "Prince Tortheldrin looked a great deal older dead than he had alive, as if the centuries had all caught up with him at once. One of his glaives lay beside him, snapped in two. I took the pieces to the Shen'dralar Ancients, who wanted to hear every detail." },
                { id = 7507, altIds = { 84555 }, name = "Nostro's Compendium", npc = "Nostro's Compendium of Dragon Slaying", class = { "WARRIOR", "PALADIN" }, optional = true },
                { id = 7508, name = "The Forging of Quel'Serrar", npc = "A Dull and Flat Elven Blade", class = { "WARRIOR", "PALADIN" }, optional = true, recap = "I returned Nostro's Compendium of Dragon Slaying to the library, and Lorekeeper Lydros mentioned what it would have fetched on the black market. Then I showed Lydros a dull, flat elven blade and got instructions back: heat it in a certain dragon's breath and temper it in her blood. Lydros said it like a recipe." },
                { id = 5518, name = "The Gordok Ogre Suit", npc = "Knot Thimblejack", optional = true, recap = "Knot Thimblejack, a goblin chained up in the Gordok wing, offered to sew me an ogre suit if I brought the runecloth, leather and ogre tannin. It would hold together for ten minutes. Knot reckoned that was plenty to fool an ogre captain, and Knot has had a long time to study ogres." },
                { id = 5525, name = "Free Knot!", npc = "Knot Thimblejack", optional = true, recap = "Knot Thimblejack had been chained up by the ogres long enough to have pet names for them. One of them was carrying the shackle key, so I let Knot go. Knot said a goblin's life was meant for more than being an ogre's appetizer, and I didn't argue." },
                { id = 7703, altIds = { 1318 }, name = "Unfinished Gordok Business", npc = "Captain Kromcrush", optional = true, recap = "Captain Kromcrush had an old story about a creepy elf calling himself a prince, who stole the Gauntlet of Gordok Might from an ogre king. The story was true, and the gauntlet was sitting in the prince's own chest. Kromcrush put the magic back into it and handed it to the new king, long live me." },
                { id = 5528, name = "The Gordok Taste Test", npc = "Stomper Kreeg", optional = true, recap = "Being king of the Gordok came with one perk worth mentioning: Stomper Kreeg, who keeps the brews, brought me free samples of the good stuff. One of them was called Kreeg's Stout Beatdown. Honest name." },
                { id = 7499, name = "Codex of Defense", npc = "Codex of Defense", class = "WARRIOR", optional = true, recap = "I found the Codex of Defense in a pile of dust in Dire Maul and gave it back to the librarians for a royal seal. Never read it. Didn't need to." },
                { id = 7501, name = "The Light and How To Swing It", npc = "The Light and How to Swing It", class = "PALADIN", optional = true, recap = "The Light and How To Swing It was gathering dust in Dire Maul, so I returned it, because that's what you do with a library book. The librarians gave me a royal seal. The title had already told me everything inside." },
                { id = 7503, name = "The Greatest Race of Hunters", npc = "The Greatest Race of Hunters", class = "HUNTER", optional = true, recap = "The librarians paid a royal seal for The Greatest Race of Hunters, which I'd found in the dust in Dire Maul. My pet wanted to chew it first. I said no, mostly." },
                { id = 7498, name = "Garona: A Study on Stealth and Treachery", npc = "Garona: A Study on Stealth and Treachery", class = "ROGUE", optional = true, recap = "Garona: A Study on Stealth and Treachery was lying in the dust in Dire Maul, unguarded. I could have sold it, but the librarians offered a royal seal, and for once honest work paid better." },
                { id = 7504, name = "Holy Bologna: What the Light Won't Tell You", npc = "Holy Bologna: What the Light Won't Tell You", class = "PRIEST", optional = true, recap = "There was a book in the dust at Dire Maul called Holy Bologna: What the Light Won't Tell You. I gave it back to the librarians for a royal seal. They didn't ask whether I'd read it, and I didn't say." },
                { id = 7505, name = "Frost Shock and You", npc = "Frost Shock and You", class = "SHAMAN", optional = true, recap = "Frost Shock and You turned up in the dust in Dire Maul, and the librarians gave me a royal seal to have it back. The elements had opinions about that title. For once I agreed with them." },
                { id = 7500, name = "The Arcanist's Cookbook", npc = "The Arcanist's Cookbook", class = "MAGE", optional = true, recap = "Somebody had left The Arcanist's Cookbook lying in the dust in Dire Maul, so I returned it to the librarians for a royal seal. Did I try any of the recipes first? I'm not saying." },
                { id = 7502, name = "Harnessing Shadows", npc = "Harnessing Shadows", class = "WARLOCK", optional = true, recap = "A tome called Harnessing Shadows was lying in the dust in Dire Maul. I gave it back to the librarians for a royal seal. Some of the company I keep would have kept it, but they're not the sort you lend books to." },
                { id = 7506, name = "The Emerald Dream...", npc = "The Emerald Dream", class = "DRUID", optional = true, recap = "I found The Emerald Dream lying in the dust in Dire Maul and took my time returning it. The librarians gave me a royal seal anyway. They'd waited this long; another afternoon did them no harm." },
            },
        },
        {
            chapter = "The Challenge",
            summary = "The Banner of Provocation is ready, and Falrin Treeshaper knows where it belongs: the middle of the Ring of Law in Blackrock Depths, planted while the Dark Irons sentence you. Somebody is bound to take offense.",
            recap = "Here's how you pick a fight in the Ring of Law on purpose. You walk into Blackrock Depths, let the Dark Irons sentence you, and while they're at it you plant the Banner of Provocation in the middle of the ring.\n\nTheldren took the hint. Theldren and his whole team of gladiators, all at once, while the crowd cheered for anybody but me. We beat them anyway. Theldren had been carrying the top piece of an amulet that once belonged to a Lord Valthalak. That name would come up again. Often.\n\nAnthion had a few parting words for me after that, and then it was home, where my boots, trousers and mantle got their turn.",
